mapper.select:
SELECT COUNT(*)
FROM sagas
WHERE saga_id = #{sagaId}

mapper.update:
UPDATE sagas
SET saga_type = #{sagaType},
    status = #{status},
    data = #{data},
    updated_at = #{updatedAt}
WHERE saga_id = #{sagaId}

mapper.select:
SELECT saga_id, saga_type, status, data, created_at, updated_at
FROM sagas
WHERE saga_id = #{sagaId}
